import type { CampaignChallenge, CampaignChapter, CampaignTable, SqlValue } from '../types'

const sqlLiteral = (value: SqlValue) => {
  if (value === null) return 'NULL'
  if (typeof value === 'number') return String(value)
  return `'${value.replace(/'/g, "''")}'`
}

const setupFrom = (tables: CampaignTable[]) => tables.map((table) => {
  const columns = table.columns.map((column) => `${column.name} ${column.type}`).join(', ')
  const rows = table.rows.length
    ? `\nINSERT INTO ${table.name} VALUES\n${table.rows.map((row) => `  (${row.map(sqlLiteral).join(', ')})`).join(',\n')};`
    : ''
  return `CREATE TABLE ${table.name} (${columns});${rows}`
}).join('\n\n')

const five = (a: string, b: string, c: string, d: string, e: string) => [a, b, c, d, e]
const mission = (value: CampaignChallenge) => value
const chapter = (value: Omit<CampaignChapter, 'setupSql'>): CampaignChapter => ({ ...value, setupSql: setupFrom(value.tables) })

