const marketplace = chapter({
  id: 'marketplace-signal', number: '01', title: 'The Marketplace Signal',
  concept: 'Filtering, sorting & expressions', concepts: ['SELECT','WHERE','ORDER BY','DISTINCT','CASE'], setting: 'Northstar Marketplace', icon: 'store', accent: '#a8ff78',
  synopsis: 'Minutes before the holiday shipping cutoff, the marketplace freezes several top sellers without explaining why. Trace the order signal, identify what deserves action, and stop a costly wave of false suspensions.',
  tables: marketplaceTables,
  challenges: [
    mission({
      id: 'marketplace-1', level: 1, title: 'Confirm the paid orders', prompt: 'Signal check',
      briefing: 'Operations needs a clean list of orders whose payment has cleared before investigating anything else.',
      task: 'Return order_id, customer, and total for paid orders. Sort by order_id.', skills: ['SELECT', 'WHERE', 'ORDER BY'],
      setupSql: '', starterSql: `SELECT order_id, customer, total\nFROM orders\n-- keep only paid orders\nORDER BY order_id;`,
      solutionSql: `SELECT order_id, customer, total\nFROM orders\nWHERE status = 'paid'\nORDER BY order_id;`,
      expectedColumns: ['order_id', 'customer', 'total'], expectedRows: [[1001,'Ava',240],[1003,'Cora',120],[1005,'Eli',150],[1006,'Farah',45],[1007,'Gus',240]], ordered: true,
      hints: five('Start with the rows in orders; no join is needed.', 'The status column describes whether money cleared.', 'Text values in SQL use single quotes.', 'Filtering happens in a WHERE clause before sorting.', "Compare status with the exact value paid, then sort on order_id."),
      explanation: { summary: 'The query narrows the order population before presenting it in a stable sequence.', steps: ['SELECT exposes only the identifier, customer, and amount needed by operations.', "WHERE status = 'paid' removes pending and refunded activity before it reaches the result.", 'ORDER BY order_id makes repeated runs deterministic and easy to audit.'], takeaway: 'Use WHERE to define the population; use ORDER BY only to control its presentation.' },
    }),
    mission({
      id: 'marketplace-2', level: 2, title: 'Surface high-value electronics', prompt: 'Priority queue',
      briefing: 'The electronics team can manually review only cleared orders worth at least $150.',
      task: 'Return order_id, customer, and total for paid Electronics orders with total at least 150. Sort total descending, then order_id ascending.', skills: ['AND', 'Comparison', 'Multi-column sort'],
      setupSql: '', starterSql: `SELECT order_id, customer, total\nFROM orders\nWHERE -- combine all three conditions\nORDER BY -- highest value first, stable ties;`,
      solutionSql: `SELECT order_id, customer, total\nFROM orders\nWHERE status = 'paid'\n  AND category = 'Electronics'\n  AND total >= 150\nORDER BY total DESC, order_id ASC;`,
      expectedColumns: ['order_id','customer','total'], expectedRows: [[1001,'Ava',240],[1007,'Gus',240]], ordered: true,
      hints: five('All three rules describe the same row, so they belong in one WHERE clause.', 'Use AND when every condition must be true.', 'At least includes the boundary value, so choose an inclusive comparison.', 'DESC places larger totals before smaller totals.', 'Add order_id ASC after total DESC to break equal-total ties.'),
      explanation: { summary: 'Three predicates construct one precise review population, and a second sort key resolves ties.', steps: ['The status predicate excludes money that has not cleared.', 'The category predicate prevents unrelated high-value orders from entering the queue.', 'total >= 150 includes orders exactly at the review threshold.', 'ORDER BY total DESC, order_id ASC prioritizes value while remaining deterministic.'], takeaway: 'Combine independent requirements with AND and always define how ties should be ordered.' },
    }),
    mission({
      id: 'marketplace-3', level: 3, title: 'Map the active regions', prompt: 'Coverage map',
      briefing: 'Leadership wants to know which fulfillment regions currently contain paid demand, without duplicate labels.',
      task: 'Return one column named region containing each distinct region with a paid order. Sort alphabetically.', skills: ['DISTINCT', 'Filtering'],
      setupSql: '', starterSql: `SELECT -- remove repeated regions\nFROM orders\nWHERE status = 'paid'\nORDER BY region;`,
      solutionSql: `SELECT DISTINCT region\nFROM orders\nWHERE status = 'paid'\nORDER BY region;`,
      expectedColumns: ['region'], expectedRows: [['East'],['South'],['West']], ordered: true, requiredTerms: ['DISTINCT'],
      hints: five('Several paid orders can share the same region.', 'The result needs unique values, not grouped metrics.', 'DISTINCT applies to the selected column combination.', 'Keep the paid filter even though only region is displayed.', 'Place DISTINCT immediately after SELECT and select region.'),
      explanation: { summary: 'DISTINCT reduces repeated paid-order regions to a set of unique coverage areas.', steps: ['WHERE first limits the source population to paid demand.', 'SELECT DISTINCT region compares the projected region values and removes duplicates.', 'ORDER BY region produces a readable alphabetical list.'], takeaway: 'DISTINCT deduplicates the selected shape; filter first so irrelevant rows do not influence that set.' },
    }),
    mission({
      id: 'marketplace-4', level: 4, title: 'Calculate net order value', prompt: 'Discount impact',
      briefing: 'Gross totals overstate value because several paid orders include discounts. Finance needs the actual post-discount amount.',
      task: 'For paid orders, return order_id, customer, and net_total calculated as total after discount, rounded to 2 decimals. Sort net_total descending, then order_id.', skills: ['Arithmetic', 'ROUND', 'Alias'],
      setupSql: '', starterSql: `SELECT order_id, customer,\n  -- calculate the discounted total\nFROM orders\nWHERE status = 'paid'\nORDER BY net_total DESC, order_id;`,
      solutionSql: `SELECT order_id, customer,\n  ROUND(total * (1 - discount_pct / 100.0), 2) AS net_total\nFROM orders\nWHERE status = 'paid'\nORDER BY net_total DESC, order_id;`,
      expectedColumns: ['order_id','customer','net_total'], expectedRows: [[1001,'Ava',216],[1007,'Gus',204],[1003,'Cora',120],[1005,'Eli',120],[1006,'Farah',45]], ordered: true,
      hints: five('A percentage must be converted into a fraction before it is used.', 'The retained share is 1 minus the discount fraction.', 'Use 100.0 rather than 100 to make decimal intent explicit.', 'ROUND accepts the expression and the number of decimal places.', 'Alias the rounded expression net_total so the sort can refer to it.'),
      explanation: { summary: 'The expression converts a percentage into a retained fraction, applies it, rounds it, and names the result.', steps: ['discount_pct / 100.0 turns values such as 15 into 0.15.', '1 minus that fraction gives the portion the customer actually pays.', 'Multiplying total by the retained portion calculates net value.', 'ROUND(..., 2) controls money precision and AS net_total gives the derived column business meaning.'], takeaway: 'Break financial expressions into units: percentage, retained share, amount, then display precision.' },
    }),
    mission({
      id: 'marketplace-5', level: 5, title: 'Build the service queue', prompt: 'Case classification',
      briefing: 'The response team needs every paid order classified into a service tier without maintaining three separate reports.',
      task: "Return order_id, customer, total, and service_tier. Use priority for totals >= 200, standard for totals >= 100, and small otherwise. Include paid orders only; sort by total descending, then order_id.", skills: ['CASE', 'Rule ordering', 'Derived labels'],
      setupSql: '', starterSql: `SELECT order_id, customer, total,\n  CASE\n    -- test the highest threshold first\n  END AS service_tier\nFROM orders\nWHERE status = 'paid'\nORDER BY total DESC, order_id;`,
      solutionSql: `SELECT order_id, customer, total,\n  CASE\n    WHEN total >= 200 THEN 'priority'\n    WHEN total >= 100 THEN 'standard'\n    ELSE 'small'\n  END AS service_tier\nFROM orders\nWHERE status = 'paid'\nORDER BY total DESC, order_id;`,
      expectedColumns: ['order_id','customer','total','service_tier'], expectedRows: [[1001,'Ava',240,'priority'],[1007,'Gus',240,'priority'],[1005,'Eli',150,'standard'],[1003,'Cora',120,'standard'],[1006,'Farah',45,'small']], ordered: true, requiredTerms: ['CASE'],
      hints: five('A searched CASE can evaluate several Boolean conditions in order.', 'CASE stops at the first WHEN that evaluates true.', 'Because 240 is also at least 100, test the 200 boundary first.', 'ELSE handles every paid total below 100.', 'Close the expression with END and alias it service_tier.'),
      explanation: { summary: 'An ordered CASE expression converts numeric thresholds into mutually exclusive operational labels.', steps: ['The >= 200 branch comes first because those rows also satisfy the lower threshold.', 'The >= 100 branch sees only rows that failed the priority rule.', 'ELSE safely captures all remaining paid orders.', 'The alias exposes the classification as service_tier while preserving the original total for verification.'], takeaway: 'CASE is first-match logic: order overlapping rules from most specific or highest priority to broadest.' },
    }),
  ],
})

