const restaurant = chapter({
  id: 'restaurant-pulse', number: '02', title: 'The Restaurant Pulse', concept: 'Aggregation & grouped reporting', concepts: ['COUNT','SUM','AVG','GROUP BY','HAVING'], setting: 'Juniper Table Group', icon: 'utensils', accent: '#ffd166',
  synopsis: 'One restaurant is celebrating record revenue while another report says the group is slipping. Before investors arrive in the morning, expose which location—and which numbers—are telling the truth.', tables: restaurantTables,
  challenges: [
    mission({ id:'restaurant-1',level:1,title:'Count completed checks',prompt:'Daily close',briefing:'The close manager needs one verified count of revenue-producing checks.',task:'Return one column named completed_orders containing the number of completed orders.',skills:['COUNT','WHERE'],setupSql:'',starterSql:`SELECT -- count matching rows AS completed_orders\nFROM restaurant_orders\nWHERE -- completed only;`,solutionSql:`SELECT COUNT(*) AS completed_orders\nFROM restaurant_orders\nWHERE status = 'completed';`,expectedColumns:['completed_orders'],expectedRows:[[7]],
      hints:five('The answer is one summary row, not a list of checks.','COUNT(*) counts rows that survive filtering.','Apply the status rule before the aggregate is calculated.','Use an alias to match the requested output name.',"Filter status to completed and name COUNT(*) completed_orders."),
      explanation:{summary:'COUNT summarizes the filtered completed-check population into one operational metric.',steps:['WHERE removes open and void checks.','COUNT(*) counts every remaining row regardless of nullable business columns.','AS completed_orders gives the metric a stable reporting name.'],takeaway:'Filter the population first, then aggregate it.'}}),
    mission({ id:'restaurant-2',level:2,title:'Revenue by location',prompt:'Location rollup',briefing:'Regional leadership needs comparable completed revenue for each location.',task:'Return location and revenue, the sum of subtotal for completed orders. Sort by location.',skills:['SUM','GROUP BY'],setupSql:'',starterSql:`SELECT location,\n  -- total completed subtotal AS revenue\nFROM restaurant_orders\nWHERE status = 'completed'\n-- one row per location\nORDER BY location;`,solutionSql:`SELECT location, SUM(subtotal) AS revenue\nFROM restaurant_orders\nWHERE status = 'completed'\nGROUP BY location\nORDER BY location;`,expectedColumns:['location','revenue'],expectedRows:[['Downtown',168],['Harbor',140],['Uptown',280]],ordered:true,
      hints:five('The requested grain is one row per location.','SUM combines subtotal values inside each group.','GROUP BY defines which rows belong to the same summary.','The status filter must exclude open and void checks before grouping.','Group on location and alias SUM(subtotal) as revenue.'),
      explanation:{summary:'The query creates one completed-revenue group per location.',steps:['WHERE defines completed checks as the valid revenue population.','GROUP BY location partitions that population into three groups.','SUM(subtotal) runs independently inside each group.','Ordering by location makes locations easy to compare across runs.'],takeaway:'The GROUP BY columns define the result grain; every aggregate is computed at that grain.'}}),
    mission({ id:'restaurant-3',level:3,title:'Measure average check size',prompt:'Guest economics',briefing:'Revenue alone hides whether a location wins through more checks or larger checks.',task:'For completed orders, return location, order_count, and avg_ticket rounded to 2 decimals. Sort by location.',skills:['COUNT','AVG','ROUND'],setupSql:'',starterSql:`SELECT location,\n  -- completed check count,\n  -- rounded average subtotal\nFROM restaurant_orders\nWHERE status = 'completed'\nGROUP BY location\nORDER BY location;`,solutionSql:`SELECT location,\n  COUNT(*) AS order_count,\n  ROUND(AVG(subtotal), 2) AS avg_ticket\nFROM restaurant_orders\nWHERE status = 'completed'\nGROUP BY location\nORDER BY location;`,expectedColumns:['location','order_count','avg_ticket'],expectedRows:[['Downtown',2,84],['Harbor',2,70],['Uptown',3,93.33]],ordered:true,
      hints:five('You can calculate several aggregates over the same groups.','COUNT(*) measures volume while AVG(subtotal) measures check size.','Both aggregates use the completed rows inside each location.','ROUND the average, not the source subtotal.','Select location, COUNT(*), and ROUND(AVG(subtotal), 2) with clear aliases.'),
      explanation:{summary:'Two aggregates describe both volume and typical value without changing the location grain.',steps:['The completed filter ensures void and unfinished checks affect neither metric.','COUNT(*) reports how many checks contribute to each location.','AVG(subtotal) divides each location total by its contributing non-null subtotals.','ROUND(..., 2) presents the derived monetary average consistently.'],takeaway:'Multiple aggregates over one GROUP BY population reveal different dimensions of performance.'}}),
    mission({ id:'restaurant-4',level:4,title:'Build the exception scorecard',prompt:'Operational health',briefing:'Managers need completed and exception counts together so every location is measured from the same source population.',task:'For every location, return location, total_orders, completed_orders, and exception_orders (anything not completed). Sort by location.',skills:['CASE','Conditional aggregation'],setupSql:'',starterSql:`SELECT location,\n  COUNT(*) AS total_orders,\n  -- count completed,\n  -- count everything else\nFROM restaurant_orders\nGROUP BY location\nORDER BY location;`,solutionSql:`SELECT location,\n  COUNT(*) AS total_orders,\n  SUM(CASE WHEN status = 'completed' THEN 1 ELSE 0 END) AS completed_orders,\n  SUM(CASE WHEN status <> 'completed' THEN 1 ELSE 0 END) AS exception_orders\nFROM restaurant_orders\nGROUP BY location\nORDER BY location;`,expectedColumns:['location','total_orders','completed_orders','exception_orders'],expectedRows:[['Downtown',3,2,1],['Harbor',3,2,1],['Uptown',3,3,0]],ordered:true,requiredTerms:['CASE'],
      hints:five('Do not filter out exceptions; both populations must remain available.','COUNT(*) gives the denominator for each location.','A CASE can turn a matching row into 1 and a nonmatch into 0.','SUM those 1 and 0 values to create a conditional count.','Use one CASE for completed and another for status not equal to completed.'),
      explanation:{summary:'Conditional aggregation calculates complementary status metrics in one grouped pass.',steps:['No WHERE clause is used because all statuses are part of the scorecard.','COUNT(*) measures the complete location population.','Each CASE converts a status condition into a numeric indicator.','SUM adds those indicators per location, yielding comparable segmented counts.'],takeaway:'Keep the full population when metrics need different conditions; put each condition inside its aggregate.'}}),
    mission({ id:'restaurant-5',level:5,title:'Recognize standout servers',prompt:'Recognition list',briefing:'The general manager will recognize servers with at least $100 in completed subtotal and wants tip performance in context.',task:'For each qualifying server, return server, order_count, revenue, and tip_pct rounded to 1 decimal (100 * total tips / total subtotal). Keep completed orders and servers with revenue at least 100. Sort revenue descending, then server.',skills:['HAVING','Aggregate arithmetic'],setupSql:'',starterSql:`SELECT server,\n  -- order count, revenue, and tip percentage\nFROM restaurant_orders\nWHERE status = 'completed'\nGROUP BY server\n-- keep groups with enough revenue\nORDER BY revenue DESC, server;`,solutionSql:`SELECT server,\n  COUNT(*) AS order_count,\n  SUM(subtotal) AS revenue,\n  ROUND(100.0 * SUM(tip) / SUM(subtotal), 1) AS tip_pct\nFROM restaurant_orders\nWHERE status = 'completed'\nGROUP BY server\nHAVING SUM(subtotal) >= 100\nORDER BY revenue DESC, server;`,expectedColumns:['server','order_count','revenue','tip_pct'],expectedRows:[['Finn',1,180,15],['Bo',1,120,20],['Eva',2,100,20]],ordered:true,requiredTerms:['HAVING'],
      hints:five('WHERE filters checks; the revenue threshold filters server groups.','Group-level filters belong in HAVING.','Overall tip percentage is total tip divided by total subtotal, not an average of row percentages.','Multiply by 100.0 before rounding to one decimal.','Use HAVING SUM(subtotal) >= 100 and order by the revenue alias descending.'),
      explanation:{summary:'The report filters source rows with WHERE, creates server groups, then filters those groups with HAVING.',steps:['WHERE keeps only completed business before any metric is calculated.','GROUP BY server establishes one output row per server.','SUM(tip) / SUM(subtotal) weights every dollar correctly; averaging row percentages would distort checks of different sizes.','HAVING evaluates the completed revenue aggregate after grouping.'],takeaway:'Use WHERE for input rows, HAVING for completed groups, and ratio-of-sums for a correctly weighted rate.'}}),
  ],
})

