const clinic = chapter({
  id:'clinic-continuity',number:'03',title:'The Continuity Gap',concept:'Joins & anti-joins',concepts:['JOIN','LEFT JOIN','NOT EXISTS','COUNT','MAX'],setting:'Cedar Health Network',icon:'heart',accent:'#78dce8',synopsis:'A high-risk patient has vanished from the follow-up report days before a care audit. Reconnect patients, visits, and providers to find every gap before someone misses critical care.',tables:clinicTables,
  challenges:[
    mission({id:'clinic-1',level:1,title:'Name completed visitors',prompt:'Encounter list',briefing:'The visit feed contains identifiers, but coordinators need patient names.',task:'Return visit_id, patient, and visit_date for completed visits. Sort by visit_id.',skills:['INNER JOIN','Aliases'],setupSql:'',starterSql:`SELECT v.visit_id,\n  -- patient name AS patient,\n  v.visit_date\nFROM visits AS v\n-- connect the patient registry\nWHERE v.status = 'completed'\nORDER BY v.visit_id;`,solutionSql:`SELECT v.visit_id, p.name AS patient, v.visit_date\nFROM visits AS v\nJOIN patients AS p ON p.patient_id = v.patient_id\nWHERE v.status = 'completed'\nORDER BY v.visit_id;`,expectedColumns:['visit_id','patient','visit_date'],expectedRows:[[501,'Alma','2026-07-01'],[503,'Bash','2026-07-02'],[504,'Celine','2026-07-03'],[506,'Esme','2026-07-06']],ordered:true,
      hints:five('The desired rows begin in visits.','patient_id is the relationship shared by visits and patients.','Use different aliases so each column source is visible.','An inner JOIN is appropriate because every listed visit must have a patient.','Join patients p ON p.patient_id = v.patient_id and alias p.name as patient.'),explanation:{summary:'The join replaces a patient foreign key with its human-readable registry value.',steps:['visits is the driving table because the report grain is one row per encounter.','The ON condition matches equal patient identifiers across the two tables.','WHERE then keeps completed encounters only.','The patient alias gives p.name the requested output label.'],takeaway:'Choose the table matching the desired grain as the starting point, then join descriptive entities by their keys.'}}),
    mission({id:'clinic-2',level:2,title:'Count visits without losing patients',prompt:'Registry coverage',briefing:'Dev has no visits and disappeared from an earlier report. The registry audit must retain everyone.',task:'Return patient_id, patient, and visit_count for every patient, including zero visits. Sort by patient_id.',skills:['LEFT JOIN','COUNT'],setupSql:'',starterSql:`SELECT p.patient_id, p.name AS patient,\n  -- count only real visit matches\nFROM patients AS p\n-- preserve the registry\nGROUP BY p.patient_id, p.name\nORDER BY p.patient_id;`,solutionSql:`SELECT p.patient_id, p.name AS patient, COUNT(v.visit_id) AS visit_count\nFROM patients AS p\nLEFT JOIN visits AS v ON v.patient_id = p.patient_id\nGROUP BY p.patient_id, p.name\nORDER BY p.patient_id;`,expectedColumns:['patient_id','patient','visit_count'],expectedRows:[[1,'Alma',2],[2,'Bash',1],[3,'Celine',2],[4,'Dev',0],[5,'Esme',1]],ordered:true,requiredTerms:['LEFT JOIN'],
      hints:five('Start with the complete patient registry.','An inner join would remove patients without matches.','LEFT JOIN preserves every row from its left side.','COUNT(*) would count the placeholder row for a patient with no visit.','Count v.visit_id because it is NULL when no real visit matched.'),explanation:{summary:'A LEFT JOIN preserves the registry, and counting a nullable right-side key distinguishes real visits from placeholders.',steps:['patients is placed on the preserved left side.','LEFT JOIN produces one NULL-filled visit row when no match exists.','COUNT(v.visit_id) ignores that NULL, correctly returning zero for Dev.','Grouping by the patient identity restores one row per patient after one-to-many expansion.'],takeaway:'For zero-inclusive counts, preserve the parent with LEFT JOIN and count a non-nullable key from the child.'}}),
    mission({id:'clinic-3',level:3,title:'Connect patients to specialists',prompt:'Clinical trail',briefing:'Quality reviewers need completed encounters with both the patient and responsible specialist visible.',task:'Return visit_id, patient, provider, and specialty for completed visits. Sort by visit_id.',skills:['Multi-table joins'],setupSql:'',starterSql:`SELECT v.visit_id,\n  p.name AS patient,\n  -- provider name and specialty\nFROM visits AS v\nJOIN patients AS p ON p.patient_id = v.patient_id\n-- connect providers\nWHERE v.status = 'completed'\nORDER BY v.visit_id;`,solutionSql:`SELECT v.visit_id, p.name AS patient,\n  pr.name AS provider, pr.specialty\nFROM visits AS v\nJOIN patients AS p ON p.patient_id = v.patient_id\nJOIN providers AS pr ON pr.provider_id = v.provider_id\nWHERE v.status = 'completed'\nORDER BY v.visit_id;`,expectedColumns:['visit_id','patient','provider','specialty'],expectedRows:[[501,'Alma','Dr. Chen','Cardiology'],[503,'Bash','Dr. Imani','Primary Care'],[504,'Celine','Dr. Rao','Neurology'],[506,'Esme','Dr. Imani','Primary Care']],ordered:true,
      hints:five('visits acts as the bridge between patients and providers.','Each relationship needs its own ON condition.','Join patients with patient_id and providers with provider_id.','Avoid reusing p for both entity aliases.','Select pr.name as provider and pr.specialty after joining providers pr.'),explanation:{summary:'The encounter fact table bridges two descriptive entities through separate foreign keys.',steps:['The first join resolves visit.patient_id to the patient registry.','The second join independently resolves visit.provider_id to the provider registry.','Aliases prevent ambiguous name columns and document each role.','The completed filter remains attached to the encounter fact.'],takeaway:'Multi-table joins are a chain of explicit relationships, not one large matching condition.'}}),
    mission({id:'clinic-4',level:4,title:'Find missing follow-up care',prompt:'Continuity gap',briefing:'A patient counts as covered only if they have a completed follow-up—not merely a scheduled or cancelled one.',task:'Return patient_id and patient for patients with no completed follow-up visit. Sort by patient_id.',skills:['NOT EXISTS','Anti-join'],setupSql:'',starterSql:`SELECT p.patient_id, p.name AS patient\nFROM patients AS p\nWHERE NOT EXISTS (\n  -- qualifying visit for this patient\n)\nORDER BY p.patient_id;`,solutionSql:`SELECT p.patient_id, p.name AS patient\nFROM patients AS p\nWHERE NOT EXISTS (\n  SELECT 1 FROM visits AS v\n  WHERE v.patient_id = p.patient_id\n    AND v.kind = 'follow-up'\n    AND v.status = 'completed'\n)\nORDER BY p.patient_id;`,expectedColumns:['patient_id','patient'],expectedRows:[[2,'Bash'],[3,'Celine'],[4,'Dev'],[5,'Esme']],ordered:true,requiredTerms:['NOT EXISTS'],
      hints:five('The question asks whether a qualifying related row exists.','Define qualifying with both kind and status.','The inner lookup must be correlated to the current patient.','NOT EXISTS keeps the patient when the lookup finds zero rows.','Inside NOT EXISTS, match v.patient_id to p.patient_id and require completed follow-up.'),explanation:{summary:'The correlated anti-join expresses the business rule directly: keep a patient only when no qualifying follow-up exists.',steps:['The outer query considers every registered patient.','The inner query searches visits for the current patient through the correlated identifier.','Both kind and status are inside the lookup, so cancelled follow-ups do not count as coverage.','NOT EXISTS negates that qualifying relationship.'],takeaway:'For “has no qualifying child” questions, put the complete qualification inside a correlated NOT EXISTS.'}}),
    mission({id:'clinic-5',level:5,title:'Audit high-risk continuity',prompt:'Risk review',briefing:'Clinical leadership wants high-risk patients retained even if they have no completed care history.',task:'For each high-risk patient, return patient_id, patient, completed_visits, and last_completed_visit. Include patients with zero completed visits. Sort by patient_id.',skills:['Filtered LEFT JOIN','MAX','Zero-inclusive metrics'],setupSql:'',starterSql:`SELECT p.patient_id, p.name AS patient,\n  -- completed count,\n  -- latest completed date\nFROM patients AS p\nLEFT JOIN visits AS v\n  ON v.patient_id = p.patient_id\n  -- qualify the match here\nWHERE p.risk_level = 'high'\nGROUP BY p.patient_id, p.name\nORDER BY p.patient_id;`,solutionSql:`SELECT p.patient_id, p.name AS patient,\n  COUNT(v.visit_id) AS completed_visits,\n  MAX(v.visit_date) AS last_completed_visit\nFROM patients AS p\nLEFT JOIN visits AS v\n  ON v.patient_id = p.patient_id\n AND v.status = 'completed'\nWHERE p.risk_level = 'high'\nGROUP BY p.patient_id, p.name\nORDER BY p.patient_id;`,expectedColumns:['patient_id','patient','completed_visits','last_completed_visit'],expectedRows:[[1,'Alma',1,'2026-07-01'],[4,'Dev',0,null]],ordered:true,requiredTerms:['LEFT JOIN'],
      hints:five('High-risk describes patients; completed describes which visits may match.','Keep the high-risk patient filter in WHERE.','Put the completed-visit condition in ON so unmatched patients survive.','COUNT a visit key for a zero and MAX the ISO date for the latest visit.','LEFT JOIN on patient_id AND completed status, then group by the patient.'),explanation:{summary:'Predicate placement preserves high-risk patients while allowing only completed visits to contribute to their metrics.',steps:['WHERE p.risk_level selects the parent population that must appear.','The completed condition belongs in ON; placing it in WHERE would reject Dev’s NULL placeholder and silently turn the join inward.','COUNT(v.visit_id) returns zero when no completed row matched.','MAX on ISO-formatted dates returns the latest completed encounter or NULL when none exists.'],takeaway:'A right-table condition in ON controls what may match; the same condition in WHERE can remove unmatched parents.'}}),
  ],
})

