const automation = chapter({id:'station-automation',number:'10',title:'The Silent Automation',concept:'Triggers & database events',concepts:['CREATE TRIGGER','OLD','NEW','WHEN','UNION ALL'],setting:'Kepler Orbital Station',icon:'zap',accent:'#c084fc',synopsis:'Someone changed a critical supply count, yet the station recorded no history and sent no warning. Install the missing safeguards before another silent correction hides a real shortage.',tables:automationTables,challenges:[
  mission({id:'triggers-1',level:1,title:'Record one stock change',prompt:'Audit hook',briefing:'Operations needs every stock update to preserve its before and after values.',task:"Create AFTER UPDATE trigger audit_stock_update on station_inventory. Insert event_type 'update', OLD.sku, OLD.stock, and NEW.stock into stock_audit. Update SKU A to stock 7, then return sku, old_stock, and new_stock from stock_audit.",skills:['CREATE TRIGGER','OLD','NEW'],setupSql:'',starterSql:`CREATE TRIGGER audit_stock_update\nAFTER UPDATE ON station_inventory\nBEGIN\n  -- write the change to stock_audit\nEND;\nUPDATE station_inventory SET stock = 7 WHERE sku = 'A';\nSELECT sku, old_stock, new_stock FROM stock_audit;`,solutionSql:`CREATE TRIGGER audit_stock_update\nAFTER UPDATE ON station_inventory\nBEGIN\n  INSERT INTO stock_audit (event_type, sku, old_stock, new_stock)\n  VALUES ('update', OLD.sku, OLD.stock, NEW.stock);\nEND;\nUPDATE station_inventory SET stock = 7 WHERE sku = 'A';\nSELECT sku, old_stock, new_stock FROM stock_audit;`,expectedColumns:['sku','old_stock','new_stock'],expectedRows:[['A',5,7]],ordered:true,requiredTerms:['CREATE TRIGGER','OLD','NEW'],hints:five('A trigger body sits between BEGIN and END.','The trigger fires once for each updated row.','OLD exposes values before the update.','NEW exposes values after the update.','Insert OLD.sku, OLD.stock, and NEW.stock into the audit destination.'),explanation:{summary:'The AFTER UPDATE trigger captures both versions of a row immediately after a successful change.',steps:['AFTER UPDATE binds the trigger to update events on station_inventory.','OLD.stock reads the value that existed before the statement.','NEW.stock reads the resulting value.','The body inserts a durable audit record in the same transaction as the original update.'],takeaway:'Use OLD and NEW to make row changes observable without duplicating audit logic in every caller.'}}),
  mission({id:'triggers-2',level:2,title:'Audit a multi-row operation',prompt:'Row-level behavior',briefing:'One maintenance statement changes several supplies, and each change needs its own audit row.',task:"Create the same stock update audit trigger. Update SKU A to 7 and SKU C to 6 in one UPDATE using CASE. Return sku, old_stock, and new_stock from stock_audit ordered by audit_id.",skills:['Row triggers','CASE update'],setupSql:'',starterSql:`CREATE TRIGGER audit_stock_update AFTER UPDATE OF stock ON station_inventory\nBEGIN\n  -- audit each changed row\nEND;\nUPDATE station_inventory\nSET stock = CASE sku WHEN 'A' THEN 7 WHEN 'C' THEN 6 END\nWHERE sku IN ('A','C');\nSELECT sku, old_stock, new_stock FROM stock_audit ORDER BY audit_id;`,solutionSql:`CREATE TRIGGER audit_stock_update AFTER UPDATE OF stock ON station_inventory\nBEGIN\n  INSERT INTO stock_audit (event_type, sku, old_stock, new_stock)\n  VALUES ('update', OLD.sku, OLD.stock, NEW.stock);\nEND;\nUPDATE station_inventory\nSET stock = CASE sku WHEN 'A' THEN 7 WHEN 'C' THEN 6 END\nWHERE sku IN ('A','C');\nSELECT sku, old_stock, new_stock FROM stock_audit ORDER BY audit_id;`,expectedColumns:['sku','old_stock','new_stock'],expectedRows:[['A',5,7],['C',2,6]],ordered:true,requiredTerms:['CREATE TRIGGER','OLD','NEW'],hints:five('SQLite row triggers run separately for every row affected by a statement.','AFTER UPDATE OF stock narrows the event to updates that target stock.','The body still inserts only one audit row per firing.','The CASE assigns a different new value by SKU.','One two-row UPDATE should therefore produce two audit rows.'),explanation:{summary:'A single SQL UPDATE can cause the same row trigger to execute multiple times.',steps:['UPDATE OF stock ties firing to statements that target the stock column.','The CASE statement changes two source rows in one operation.','SQLite invokes the trigger body once with A’s OLD/NEW pair and once with C’s pair.','audit_id ordering exposes the separate event records.'],takeaway:'Understand whether your database uses row- or statement-level triggers before reasoning about trigger volume.'}}),
  mission({id:'triggers-3',level:3,title:'Alert only below threshold',prompt:'Conditional automation',briefing:'Routine updates should stay quiet; operations wants an alert only when the resulting stock is below that item’s threshold.',task:"Create AFTER UPDATE OF stock trigger low_stock_alert with a WHEN condition for NEW.stock < NEW.reorder_point. Insert NEW.sku and message 'Stock below reorder point' into stock_alerts. Update B to 3 and A to 4, then return sku and message sorted by alert_id.",skills:['WHEN','Conditional trigger'],setupSql:'',starterSql:`CREATE TRIGGER low_stock_alert\nAFTER UPDATE OF stock ON station_inventory\n-- add a row-level condition\nBEGIN\n  -- insert the alert\nEND;\nUPDATE station_inventory SET stock = 3 WHERE sku = 'B';\nUPDATE station_inventory SET stock = 4 WHERE sku = 'A';\nSELECT sku, message FROM stock_alerts ORDER BY alert_id;`,solutionSql:`CREATE TRIGGER low_stock_alert\nAFTER UPDATE OF stock ON station_inventory\nWHEN NEW.stock < NEW.reorder_point\nBEGIN\n  INSERT INTO stock_alerts (sku, message)\n  VALUES (NEW.sku, 'Stock below reorder point');\nEND;\nUPDATE station_inventory SET stock = 3 WHERE sku = 'B';\nUPDATE station_inventory SET stock = 4 WHERE sku = 'A';\nSELECT sku, message FROM stock_alerts ORDER BY alert_id;`,expectedColumns:['sku','message'],expectedRows:[['B','Stock below reorder point']],ordered:true,requiredTerms:['CREATE TRIGGER','WHEN','NEW'],hints:five('A trigger WHEN clause decides whether its body runs for a firing row.','Compare the resulting NEW stock with that same row’s NEW reorder_point.','Below is strict; equality should not alert.','B ends at 3 below 5, while A ends exactly at 4.','Put WHEN before BEGIN and insert NEW.sku in the body.'),explanation:{summary:'The WHEN predicate prevents non-actionable trigger firings from producing alerts.',steps:['AFTER UPDATE OF stock identifies relevant event types.','WHEN evaluates the completed row image through NEW values.','The strict less-than rule alerts B but correctly ignores A at its threshold.','The body stays focused on the side effect needed only for qualifying rows.'],takeaway:'Put precise business qualification in a trigger WHEN clause so routine events remain silent.'}}),
  mission({id:'triggers-4',level:4,title:'Archive before deletion',prompt:'Deletion safety net',briefing:'Obsolete supplies may be deleted, but their final state must survive in a lightweight archive.',task:'Create BEFORE DELETE trigger archive_supply. Insert OLD.sku, OLD.item, and OLD.stock into retired_supplies. Delete SKU C, then return sku, item, and final_stock from retired_supplies.',skills:['BEFORE DELETE','OLD'],setupSql:'',starterSql:`CREATE TRIGGER archive_supply\nBEFORE DELETE ON station_inventory\nBEGIN\n  -- archive the departing OLD row\nEND;\nDELETE FROM station_inventory WHERE sku = 'C';\nSELECT sku, item, final_stock FROM retired_supplies;`,solutionSql:`CREATE TRIGGER archive_supply\nBEFORE DELETE ON station_inventory\nBEGIN\n  INSERT INTO retired_supplies (sku, item, final_stock)\n  VALUES (OLD.sku, OLD.item, OLD.stock);\nEND;\nDELETE FROM station_inventory WHERE sku = 'C';\nSELECT sku, item, final_stock FROM retired_supplies;`,expectedColumns:['sku','item','final_stock'],expectedRows:[['C','Coolant',2]],ordered:true,requiredTerms:['CREATE TRIGGER','BEFORE DELETE','OLD'],hints:five('A deleted row has no NEW image.','OLD remains available to the delete trigger.','BEFORE DELETE makes the archive intent clear before the row disappears.','Map OLD.stock to the archive column final_stock.','Insert the three OLD values inside the trigger body.'),explanation:{summary:'The delete trigger copies the final OLD row image into an archive before the source row disappears.',steps:['BEFORE DELETE binds the action to the deletion lifecycle.','OLD supplies every departing inventory value.','The archive uses a differently named final_stock column, so the INSERT column list documents the mapping.','The delete and archive insert share the same transaction.'],takeaway:'Deletion triggers can preserve essential history, but the archive schema should remain intentional and minimal.'}}),
  mission({id:'triggers-5',level:5,title:'Detect a threshold crossing',prompt:'Automation capstone',briefing:'An alert should fire when healthy stock crosses below its threshold—not every time already-low stock decreases again. All updates still require auditing.',task:"Create audit_stock_update for every stock update and crossing_alert that fires only when NEW.stock < NEW.reorder_point and OLD.stock >= OLD.reorder_point. Update A to 3 and C to 1. Return a combined record_type, sku, value result: alerts as record_type 'alert' with NULL value, audits as 'audit' with new_stock value. Sort by record_type, sku.",skills:['Multiple triggers','State transition','UNION ALL'],setupSql:'',starterSql:`-- create the audit trigger\n-- create the threshold-crossing alert trigger\nUPDATE station_inventory SET stock = 3 WHERE sku = 'A';\nUPDATE station_inventory SET stock = 1 WHERE sku = 'C';\nSELECT 'alert' AS record_type, sku, NULL AS value FROM stock_alerts\nUNION ALL\nSELECT 'audit', sku, new_stock FROM stock_audit\nORDER BY record_type, sku;`,solutionSql:`CREATE TRIGGER audit_stock_update AFTER UPDATE OF stock ON station_inventory\nBEGIN\n  INSERT INTO stock_audit (event_type, sku, old_stock, new_stock) VALUES ('update', OLD.sku, OLD.stock, NEW.stock);\nEND;\nCREATE TRIGGER crossing_alert AFTER UPDATE OF stock ON station_inventory\nWHEN NEW.stock < NEW.reorder_point AND OLD.stock >= OLD.reorder_point\nBEGIN\n  INSERT INTO stock_alerts (sku, message) VALUES (NEW.sku, 'Crossed below reorder point');\nEND;\nUPDATE station_inventory SET stock = 3 WHERE sku = 'A';\nUPDATE station_inventory SET stock = 1 WHERE sku = 'C';\nSELECT 'alert' AS record_type, sku, NULL AS value FROM stock_alerts\nUNION ALL\nSELECT 'audit', sku, new_stock FROM stock_audit\nORDER BY record_type, sku;`,expectedColumns:['record_type','sku','value'],expectedRows:[['alert','A',null],['audit','A',3],['audit','C',1]],ordered:true,requiredTerms:['CREATE TRIGGER','OLD','NEW','UNION ALL'],hints:five('Auditing describes every update; alerting describes only a transition.','A transition predicate must compare both OLD and NEW states.','A crosses from 5 at/above 4 to 3 below 4.','C begins below 3, so moving from 2 to 1 should not create another crossing alert.','Use two focused triggers, then UNION ALL their verification records.'),explanation:{summary:'Two small triggers separate universal history from exceptional state-transition notification.',steps:['The audit trigger records both A and C because every stock update matters historically.','The alert trigger tests NEW below threshold and OLD at or above threshold, which models crossing rather than simply being low.','A satisfies both halves; C fails the OLD-state half because it was already low.','UNION ALL combines two verification streams without confusing their different meanings.'],takeaway:'Event automation is clearest when each trigger owns one responsibility and transition rules compare OLD with NEW.'}}),
]})

